package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.*;import com.jnapanam.sportszone.notification.service.NotificationProviderSettingsService;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class Fast2SmsNotificationProvider implements SmsNotificationProvider{private final RestClient http=RestClient.create();private final String url,key,senderId,route,otpUrl,otpId;private final NotificationProviderSettingsService settings;public Fast2SmsNotificationProvider(@Value("${app.notification.sms.fast2sms.url:https://www.fast2sms.com/dev/bulkV2}")String url,@Value("${app.notification.sms.fast2sms.api-key:}")String key,@Value("${app.notification.sms.fast2sms.sender-id:}")String senderId,@Value("${app.notification.sms.fast2sms.route:q}")String route,@Value("${app.notification.sms.fast2sms.otp-url:https://www.fast2sms.com/dev/otp/send}")String otpUrl,@Value("${app.notification.sms.fast2sms.otp-id:}")String otpId,NotificationProviderSettingsService settings){this.url=url;this.key=key;this.senderId=senderId;this.route=route;this.otpUrl=otpUrl;this.otpId=otpId;this.settings=settings;}public NotificationChannel channel(){return NotificationChannel.SMS;}public String name(){return "fast2sms";}public String send(Notification n){return sendTo(n.getUser().getMobile(),n.getMessage());}public String sendTo(String mobile,String message){String activeKey=settings.value("FAST2SMS_API_KEY",key);if(activeKey==null||activeKey.isBlank())throw new IllegalStateException("FAST2SMS_API_KEY is not configured");if(mobile==null||mobile.isBlank())throw new IllegalStateException("Mobile is missing");Map<String,Object> body=new LinkedHashMap<>();body.put("route",route);body.put("message",message);body.put("numbers",normalize(mobile));String activeSender=settings.value("FAST2SMS_SENDER_ID",senderId);if(activeSender!=null&&!activeSender.isBlank())body.put("sender_id",activeSender);Map response=http.post().uri(url).header("Authorization",activeKey).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);if(response!=null&&Boolean.FALSE.equals(response.get("return")))throw new IllegalStateException(String.valueOf(response.getOrDefault("message","Fast2SMS rejected request")));Object id=response==null?null:response.get("request_id");return id==null?"fast2sms-"+UUID.randomUUID():id.toString();}public String sendOtp(String mobile,String otp){String activeKey=settings.value("FAST2SMS_API_KEY",key);if(activeKey==null||activeKey.isBlank())throw new IllegalStateException("FAST2SMS_API_KEY is not configured");String activeOtpId=settings.value("FAST2SMS_OTP_ID",otpId);if(activeOtpId==null||activeOtpId.isBlank())throw new IllegalStateException("FAST2SMS_OTP_ID is not configured");Map<String,Object> body=new LinkedHashMap<>();body.put("mobile",normalize(mobile));body.put("otp_id",activeOtpId);body.put("otp_expiry",5);body.put("otp_length",6);body.put("otp",otp);Map response=http.post().uri(otpUrl).header("Authorization",activeKey).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);Object id=response==null?null:response.get("request_id");return id==null?"fast2sms-otp-"+UUID.randomUUID():id.toString();}private String normalize(String s){String d=s.replaceAll("\\D","");return d.startsWith("91")&&d.length()==12?d.substring(2):d;}}
